/* BmsOutMapper.updatePkgSampleInfo  : 견품반출 관련 박스정보 갱신 */
UPDATE TB_BMS_IN_PLAN_PKG


	SAMPLE_IN_CT = #{sampleInCt},


	SAMPLE_OUT_CT = #{sampleOutCt},

	UPDATE_USER_ID 		= #{updateUserId},
	UPDATE_DATE_TIME 	= GETDATE()

WHERE IN_PLAN_NO = (
	SELECT TOP 1 IN_PLAN_NO FROM TB_BMS_IN _in WHERE _in.CARGO_REFERENCE_NO = #{cargoReferenceNo}
)

/* BmsOutMapper.updateInitPkgAndTic  : 박스, tic로그 초기화 */
DECLARE  @v_CARGO_REFERENCE_NO  VARCHAR(20);
DECLARE  @v_IN_PLAN_NO  INT;

SELECT TOP 1
	@v_CARGO_REFERENCE_NO  = CARGO_REFERENCE_NO
FROM  TB_BMS_OUT WITH (NOLOCK)
WHERE
	OUT_NO = #{outNo}
;

SELECT TOP 1
	@v_IN_PLAN_NO  = IN_PLAN_NO
FROM  TB_BMS_IN WITH (NOLOCK)
WHERE
	CARGO_REFERENCE_NO = @v_CARGO_REFERENCE_NO
	AND IN_PLAN_NO > 0
;

UPDATE TB_BMS_IN_PLAN_PKG SET
	 MOVE_OUT_CT = 0
	,MOVE_IN_CT = 0
	,TIC_STATUS = ''
	, UPDATE_USER_ID = #{updateUserId}
	, UPDATE_DATE_TIME = GETDATE()
FROM TB_BMS_IN_PLAN_PKG WITH (NOLOCK)
WHERE IN_PLAN_NO = @v_IN_PLAN_NO
;

UPDATE TB_BMS_TIC_MOVE_SCAN SET 
	  OUT_BACK_IN_FINISH_YN = 'Y'
WHERE OUT_NO = #{outNo};

