	*
FROM TB_BMS_OUT_PLAN outPlan WITH(NOLOCK)
WHERE CARGO_REFERENCE_NO = #{cargoReferenceNo}
	AND APPROVAL_CLASS = '31'

/* BmsOutMapper.selectBmsInMinusStock : 화물관리번호에 해당하는 마이너스(0>STOCK_CT) 재고인 반입 */
