/* BmsOutMapper.selectBmsOutDetail : 반출 상세 조회 */ select TOP 1 OUT_NO , CUSTOMS_REPORT_NO , LAST_POD_DATE , LAST_POD_STATUS , LAST_POD_RAQ_DATE , APPROVAL_DATE , OUT_CLASS , OUT_APPROVAL_NO , OD_JOB_NO , IN_NO , OUT_PLAN_NO , CARGO_REFERENCE_NO , BL_NO , MBL_NO , DO_NO , DO_DATE , CUSTOMS_CODE , CUSTOMS_DPT_CODE , CUSTOMER_CODE , CUSTOMER_NAME , BROKER_CODE , BROKER_NAME , PKG_TYPE , APPROVAL_CT , APPROVAL_WT , APPROVAL_CBM , OUT_CT , OUT_WT , OUT_CBM , CARRYOUT_DATE , CARRYOUT_TIME , APPROVAL_DUTY , APPROVAL_APPRAISE_VALUE , INS_PAYMENT_TYPE , CURRENCY_CODE , INS_PAYMENT_YN , INSPECT_YN , HS_CODE , CRITERIA_CODE , INOUT_DATE_DIFF , REMARKS_1 , REMARKS_2 , REMARKS_3 , REFERENCE_NO , REGISTER_USER_ID , REGISTER_DATE_TIME , UPDATE_USER_ID , UPDATE_DATE_TIME , (SELECT USER_NAME FROM TB_SMS_USER WHERE USER_ID = A.REGISTER_USER_ID) AS REGISTER_USER_NAME , (SELECT USER_NAME FROM TB_SMS_USER WHERE USER_ID = A.UPDATE_USER_ID) AS UPDATE_USER_NAME FROM
TB_BMS_OUT_CHANGE_DEL A
TB_BMS_OUT A WITH (NOLOCK)
where (1=1)
AND IN_NO = #{srchInNo}
AND OUT_PLAN_NO = #{srchOutPlanNo}
AND OUT_NO = #{srchOutNo}
