/* BmsOutMapper.selectBmsOutPlanDetail : 반출통고 상세 조회 */ SELECT TOP 1 OUT_PLAN_NO , NOTIFY_DATE_TIME , APPROVAL_CLASS , OUT_CLASS , OUT_APPROVAL_NO , APPROVAL_DATE , APPROVAL_CANCEL_DATE , BONDED_WAREHOUSE_NO , LOCATION_CONFIRM_NO , IN_NO , CARGO_REFERENCE_NO , BL_NO , MBL_NO , DUTY , APPRAISE_VALUE , DELIVERY_TERMS , VESSEL_FLIGHT , VOYAGE , AR_DATE , COMMODITY_ITEM_LOC , dbo.Cryptography(CARGO_REFERENCE_NO, COMPANY_BUSINESS_NO, 1) AS COMPANY_BUSINESS_NO , COMPANY_NAME , COMPANY_PRESIDENT , PKG_TYPE , APPROVAL_CT , APPROVAL_WT , APPROVAL_CBM , INS_PAYMENT_TYPE , CURRENCY_CODE , INS_PAYMENT_YN , CNTR_NO_APP , OUT_YN , INSPECT_YN , HS_CODE , CRITERIA_CODE , APPCANCEL_DATE_DIFF , INAPP_DATE_DIFF , OUT_SCAN_DATE_TIME FROM TB_BMS_OUT_PLAN WITH (NOLOCK) WHERE (1=1)
AND IN_NO = #{srchInNo}
AND OUT_PLAN_NO = #{srchOutPlanNo}
ORDER BY OUT_PLAN_NO DESC

/* BmsOutMapper.selectBmsOutSampleDetail : 견품반출 상세 조회 */ SELECT TOP 1 SAMPLE_NO , IN_NO , CARGO_REFERENCE_NO , BL_NO , MBL_NO , OD_JOB_NO , PERMISSION_DATE , PERMISSION_NO , CARRYOUT_DATE , CARRYOUT_TIME , SAMPLE_EMPLOYEE_NAME , dbo.Cryptography(OD_JOB_NO, SAMPLE_EMPLOYEE_TEL, 1) AS SAMPLE_EMPLOYEE_TEL , ARRIVE_NAME , ARRIVE_ADDRESS , COMMODITY_ITEM_LOC , SAMPLE_CT , PIECES_TYPE , SAMPLE_PIECES , SAMPLE_WT , SAMPLE_REMARKS , RETURN_DATE , RETURN_TIME , RETURN_REMARKS , RETURN_ACCEPTOR , SPECIAL_REMARKS , REGISTER_USER_ID , REGISTER_DATE_TIME , UPDATE_USER_ID , UPDATE_DATE_TIME , (SELECT USER_NAME FROM TB_SMS_USER WHERE USER_ID = A.REGISTER_USER_ID) AS REGISTER_USER_NAME , (SELECT USER_NAME FROM TB_SMS_USER WHERE USER_ID = A.UPDATE_USER_ID) AS UPDATE_USER_NAME FROM TB_BMS_SAMPLE A WHERE (1=1)
AND SAMPLE_NO = #{sampleNo}
AND IN_NO = #{srchInNo}
ORDER BY SAMPLE_NO DESC

