mapper.select:
/** BmsOutMapper.selectBmsOutFtpList */ SELECT '11110' AS PART , '' AS IN_NO1 /* 07.30 공백요청 hs */ , '' AS IN_NO2 /* 07.30 공백요청 hs */ , (CASE WHEN A.CARGO_REFERENCE_NO IS NULL THEN '' ELSE SUBSTRING(A.CARGO_REFERENCE_NO, 1, 11) END) AS MRN , (CASE WHEN A.CARGO_REFERENCE_NO IS NULL THEN '' ELSE SUBSTRING(A.CARGO_REFERENCE_NO, 12, 4) END) AS MSN , (CASE WHEN A.CARGO_REFERENCE_NO IS NULL THEN '' ELSE SUBSTRING(A.CARGO_REFERENCE_NO, 16, 4) END) AS HSN , '14' AS PKG_GBN , CONVERT(varchar, GETDATE(), 112) + REPLACE(CONVERT(varchar, GETDATE(), 108), ':', '') AS IN_DT , '040' AS CUS_CD1 , eb03.SET_VALUE AS OWNER_CD , eb04.SET_VALUE AS OWNER_COMP , '99' AS ITEM_CD , B.COMMODITY_ITEM_LOC AS ITEM_NM1 , B.MBL_NO AS MBL_NO , B.BL_NO AS HBL_NO , B.VESSEL_FLIGHT AS SHIP_NO , '21' AS IN_GUBUN , '' AS BOND_FM /* 공백 8자리 */ , '' AS BOND_TO /* 공백 8자리 */ , '' AS SINGO_REQNO /* 공백 20자리 */ , '' AS BOND_COMP_CD /* 공백 20자리 */ , B.PKG_TYPE AS PACK_KIND , 'OKY' AS IN_SAGO_CD , A.OUT_CT AS PACK_CNT , ' ' AS OUT_QTY /* 07.30 공백요청 hs 8자리 */ , ' ' AS JEGO_QTY /* 07.30 공백요청 hs 8자리*/ , A.OUT_WT AS TOT_WGT , ' ' AS OUT_WGT /* 07.30 공백요청 hs 10자리*/ , ' ' AS JEGO_WGT /* 07.30 공백요청 hs 10자리*/ , '000000' AS TOT_CBM , '000000' AS OUT_CBM1 , '000000' AS OUT_CBM , eb03.SET_VALUE AS PLC_LOC , '' AS PLC_CONF_DT /* 공백 8자리 */ , '' AS PLC_CONF_ID /* 공백 10자리 */ , '0' AS OVER_YN , '' AS OVER_NO , REPLACE(B.PERIOD_OVER_DATE,'-','') AS OVER_DT /* 07.30 hs BMS_IN 체화일자8자리 PERIOD_OVER_DATE 10자리 8자리 */ , 'I' AS DATA_CREAT_GBN , '' AS USER_ID , '' AS USER_PW , CONVERT(varchar, GETDATE(), 112) AS WORK_DT , '' AS TERM_ID , '0' AS ELEC_YN
, (CASE WHEN B.CD_TYPE = 'Y' THEN '1' ELSE '4' END) AS IN_TYPE
, (CASE WHEN B.CD_TYPE = 'Y' THEN '1' ELSE '4' END) AS IN_TYPE
, '' AS SPC_PKG_GBN , '' AS JOUP_DT , REPLACE(B.AR_DATE,'-', '') + REPLACE(B.AR_TIME,':','')+'00' AS IN_PORT_DT /* 07.30 hs artime추가 요청 */ , '' AS VAL , '' AS DUTY , '040' AS UNLD_PORT_CD , B.ORIG_COUNTRY AS SEND_NAT_CD , B.SHIPPER_NAME AS SEND_OFFICE , SUBSTRING(B.SHIPPER_ADDRESS_1,1,50) AS SEND_ADDR1 , SUBSTRING(B.SHIPPER_ADDRESS_1,51,50) AS SEND_ADDR2 , SUBSTRING(B.SHIPPER_ADDRESS_1,101,50) AS SEND_ADDR3 , dbo.Cryptography(B.OD_JOB_NO, B.CONSIGNEE_TEL, 1) AS RECV_TEL , B.CONSIGNEE_NAME AS RECV_NM , SUBSTRING(B.CONSIGNEE_ADDRESS_1,1,50) AS RECV_ADDR1 , SUBSTRING(B.CONSIGNEE_ADDRESS_1,51,50) AS RECV_ADDR2 , SUBSTRING(B.CONSIGNEE_ADDRESS_1,101,50) AS RECV_ADDR3 , '' AS RECV_POST_NO , '' AS ELEC_DOMAIN , '' AS INV_AMT , '' AS INV_AMT_UNIT , '' AS DIRECT_NO , B.ECM_TYPE AS TRADE_TYPE , B.CD_USE_TYPE AS USE_GBN , '' AS CONTR_NO1 , '' AS CONTR_NO2 , eb03.SET_VALUE AS FWD_CODE , eb04.SET_VALUE AS FWD_FIRM , B.XRAY_INSPECTION_CODE , (case B.XRAY_INSPECTION_CODE when '01' then '1' when '02' then '2' when '03' then '3' when '04' then '4' when '05' then '4' when '06' then '6' else '' end ) AS PASS_REASION , '' AS TAKBAE_NO , '' AS TAKBAE_LOC , '' AS UNI_MATT , A.LAST_POD_STATUS /* BMS04 체크용 */ , A.OUT_CLASS /* 61.이고반출(적출입작업) 확인용 */ , A.OUT_APPROVAL_NO /* 04002001 근거 번호 확인용 */ , A.OUT_NO , A.TIC_OUT_FTP_SEND_YN /* TIC이고반출FTP전송여부 */ FROM TB_BMS_OUT A WITH (NOLOCK) LEFT JOIN TB_BMS_IN B WITH (NOLOCK) ON A.IN_NO = B.IN_NO LEFT JOIN TB_SMS_ENT_BUS_OPTION eb03 ON eb03.ENT_CODE = #{srchEntCode} AND eb03.ENT_BUSINESS_CODE = #{srchEntBusinessCode} AND eb03.OPTION_CODE ='A03' LEFT JOIN TB_SMS_ENT_BUS_OPTION eb04 ON eb04.ENT_CODE = #{srchEntCode} AND eb04.ENT_BUSINESS_CODE = #{srchEntBusinessCode} AND eb04.OPTION_CODE ='A04' WHERE 1 = 1 AND A.OUT_NO IN
#{outNo}

