/* BmsOutMapper.selectBmsInFirstInByCargoNo : 입항반입혹은 보세운송반입 조회 */
SELECT TOP 1 * 
FROM TB_BMS_IN WITH (NOLOCK)
WHERE CARGO_REFERENCE_NO = #{cargoReferenceNo}
	AND (IN_CLASS = '10' OR IN_CLASS = '20')
ORDER BY CARRYIN_DATE DESC

