mapper.select:
/* BmsOutMapper.selectBmsEncourageNotiList : 선반입반출신고독려통보 조회 */
SELECT AA.* , COUNT(*) OVER() AS TOTAL_CNT , SUM(AA.SIMPLE_CNT) OVER() AS TOTAL_SIMPLE_CNT , SUM(AA.GENERAL_CNT) OVER() AS TOTAL_GENERAL_CNT FROM ( SELECT A.ENCOURAGE_NOTI_NO , CASE WHEN (SELECT TOP 1 REFERENCE_NO_ID FROM TB_COM_FILE_SHARE WHERE FUNC_JOB_NO = B.OD_JOB_NO) IS NULL THEN 'N' ELSE 'Y' END AS FILE_SHARE
, '조회' AS blStatus
, B.CD_TYPE + '.' + (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL det WHERE det.CODE = B.CD_TYPE AND det.GROUP_CODE = 'CD_TYPE') AS CD_TYPE
, B.CD_TYPE
, IIF(B.CD_TYPE = 'Y', 1, 0) AS SIMPLE_CNT , IIF(ISNULL(B.CD_TYPE, '') != 'Y', 1, 0) AS GENERAL_CNT , B.OD_JOB_NO , A.OUT_YN , B.CARRYIN_DATE , A.APPROVAL_DATE , B.BL_NO , B.MBL_NO , A.CARGO_REFERENCE_NO , A.OUT_APPROVAL_NO , A.BWH_ID , ISNULL(A.APPROVAL_CT, 0) AS APPROVAL_CT , ISNULL(A.APPROVAL_WT, 0) AS APPROVAL_WT , A.REGISTER_USER_ID , (SELECT USER_NAME FROM TB_SMS_USER WHERE USER_ID = A.REGISTER_USER_ID) AS REGISTER_USER_NAME , A.REGISTER_DATE_TIME FROM TB_BMS_ENCOURAGE_NOTI A LEFT JOIN TB_BMS_IN B WITH (NOLOCK) ON A.CARGO_REFERENCE_NO = B.CARGO_REFERENCE_NO WHERE 1=1
AND ${srchDateGbn} >= #{srchStartDate}
AND ${srchDateGbn} <= #{srchEndDate}
) AA

/* BmsOutMapper.selectErrorDesc : 등록 ENTRY - 오류내역 조회 */
SELECT TOP 1 ERROR_DESC
  FROM GT_XML_GOVCBRR20
 WHERE DECLARATION_NO = #{srchDeclarationNo} /* 신고번호 or 화물관리번호 */
   AND DOC_TYPE = #{srchDocType}
 ORDER BY ERROR_NO DESC

/*BmsOutMapper.selectCustomerInfoByBusNo*/
SELECT TOP 1 cus.CUSTOMER_CODE, cus.CUSTOMER_NAME
FROM VTB_SMS_BUSINESS_REG_INFO inf
JOIN TB_SMS_CUSTOMER cus 
on inf.ENT_CODE = cus.ENT_CODE 
AND inf.REGISTRATION_CODE = cus.REGISTRATION_CODE
WHERE inf.ENT_CODE = #{srchEntCode}
AND inf.BUSINESS_ID =  dbo.Cryptography(#{cargoReferenceNo}, #{srchCompanyBusinessNo}, 1);

/* BmsOutMapper.selectCustomsReportNoOrCargoNoFromInOut - 반입,출입에서 반입번호로 조회해서 각각의 신고번호와 화물관리번호를 조회한다 */ SELECT _in.CUSTOMS_REPORT_NO AS CUSTOMS_REPORT_NO_632 , _in.CARGO_REFERENCE_NO AS CARGO_REFERENCE_NO_632 , _out.CUSTOMS_REPORT_NO AS CUSTOMS_REPORT_NO_6NB , _out.CARGO_REFERENCE_NO AS CARGO_REFERENCE_NO_6NB
FROM TB_BMS_IN _in WITH (NOLOCK) LEFT JOIN TB_BMS_OUT _out WITH (NOLOCK) ON _in.IN_NO = _out.IN_NO WHERE _in.IN_NO = #{inNo}
FROM TB_BMS_OUT _out WITH (NOLOCK) LEFT JOIN TB_BMS_IN _in WITH (NOLOCK) ON _in.IN_NO = _out.IN_NO WHERE _out.IN_NO = #{inNo}

mapper.insert:
/* BmsOutMapper.insertBmsAllocateCarNotiByInClass - 이고반입 관련 배차예정정보 저장 */ DECLARE @vCnt INT;
SELECT @vCnt = COUNT(*) FROM TB_BMS_ALLOCATE_CAR_NOTI WHERE APPROVAL_NO = '04002001' AND INOUT_CLASS = 'I' AND OUT_EST_DATE = CONVERT(VARCHAR(10),GETDATE(),120)
IF (@vCnt = 0) BEGIN /* 등록된 자료 없으면 */ INSERT INTO TB_BMS_ALLOCATE_CAR_NOTI( CUSTOMS_REPORT_NO , APPROVAL_NO , CHANGE_CLASS , INOUT_CLASS , NOTIFY_DATE_TIME , DEPARTURE_LOC_CODE , LAST_LOC_CODE , OUT_EST_DATE , COMPANY_TRUCK_NO , REAL_TRUCK_NO , COMPANY_TRUCK_DRIVER , COMPANY_TRUCK_TEL , CARGO_REFERENCE_NO , CNTR_NO , ACCEPTOR , ALLOCATE_YN , REGISTER_USER_ID , REGISTER_DATE_TIME , UPDATE_USER_ID , UPDATE_DATE_TIME ) VALUES( '21.이고반입' , '04002001' , '1' , 'I' , GETDATE() , '04002001' , #{bmsWhCode} , CONVERT(VARCHAR(10),GETDATE(),120) , '' , '' , '' , '' , '' , '' , '' , 'N' , #{registerUserId} , GETDATE() , #{updateUserId} , GETDATE() ); END /* 등록자료는 SKIP */

