/* BmsOutMapper.updateBmsOutLastPodStatus : 반출신고저장시 접수처리 */
UPDATE TB_BMS_OUT
	SET LAST_POD_STATUS = 'BMS04'
		, UPDATE_USER_ID = #{updateUserId}
	 	, UPDATE_DATE_TIME = GETDATE()
WHERE OUT_NO = #{outNo}

/* BmsOutMapper.updateBmsOutCustomsInspect : 반출 진행상태 세관검사장(BMSA2) 변경 */
UPDATE TB_BMS_OUT
	SET LAST_POD_STATUS = 'BMSA2'
		, UPDATE_USER_ID = #{updateUserId}
	 	, UPDATE_DATE_TIME = GETDATE()
WHERE OUT_NO = #{outNo}
	AND LAST_POD_STATUS <> 'BMS04'

