/* BmsOutMapper.selectBmsOutByOutNo : 반출번호에 해당하는 반출 */
SELECT
	*
FROM TB_BMS_OUT WITH (NOLOCK)
	WHERE OUT_NO = #{outNo}

/* BmsOutMapper.selectBmsOutWithBmsIn : 반출번호,화물관리번호에 해당하는 반출정보 with 반입,박스 */
DECLARE  @v_IN_PLAN_NO  INT;

SELECT TOP 1
	@v_IN_PLAN_NO = I.IN_PLAN_NO
FROM 
	TB_BMS_OUT O WITH (NOLOCK)
	INNER JOIN TB_BMS_IN I WITH (NOLOCK) ON O.IN_NO = I.IN_NO
WHERE O.OUT_NO = #{outNo}
	AND I.IN_PLAN_NO > 0
;

IF @v_IN_PLAN_NO IS NULL
BEGIN
	SELECT 
		@v_IN_PLAN_NO = IN_PLAN_NO
	FROM TB_BMS_IN WITH (NOLOCK)
	WHERE CARGO_REFERENCE_NO = #{cargoReferenceNo}
		AND IN_PLAN_NO > 0
END

SELECT TOP 1
	@v_IN_PLAN_NO AS IN_PLAN_NO
	, I.BL_NO
	, I.OD_JOB_NO
	, I.CT
    , I.IN_NO AS IN_NO
    , O.OUT_NO
    , O.OUT_CT
FROM 
	TB_BMS_OUT O WITH (NOLOCK)
	INNER JOIN TB_BMS_IN I WITH (NOLOCK) ON O.IN_NO = I.IN_NO
WHERE O.OUT_NO = #{outNo}

/* BmsOutMapper.updateBmsOutLastPodStatus : 반입예정번호에 해당하는 박스리스트 */
SELECT
	*
FROM 
	TB_BMS_IN_PLAN_PKG WITH (NOLOCK)
WHERE IN_PLAN_NO = #{inPlanNo}

/* BmsOutMapper.selectCheckBmsOut61Count : 화물관리번호에 해당하는 이고반출 count */
SELECT count(*) 
FROM TB_BMS_OUT WITH (NOLOCK)
WHERE CARGO_REFERENCE_NO = #{cargoReferenceNo}
  AND OUT_CLASS ='61'

