/* BmsOutMapper.getSumOutCtWtGroupBmsOut : 반출 총합 */
SELECT 
	SUM(OUT_CT) AS S_OUT_CT
	, SUM(OUT_WT) AS S_OUT_WT
FROM TB_BMS_OUT WHERE IN_NO = #{inNo}

/* BmsOutMapper.getSumOutCtWtGroupBmsOutWithout : 반출 총합 (해당 반출 제외) */
SELECT 
	SUM(OUT_CT) AS S_OUT_CT
	, SUM(OUT_WT) AS S_OUT_WT
FROM TB_BMS_OUT WHERE IN_NO = #{inNo} AND OUT_NO != #{outNo}

/* BmsOutMapper.getInCtWtBmsOut : 반입 수량,중량 */
SELECT 
	CT, WT
FROM TB_BMS_IN WHERE IN_NO = #{inNo}

